import{_ as e,o as i,c as r,a5 as a}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"安全概览","description":"OWASP Top 10 是 Web 应用重要安全风险的清单。了解它们是安全编码的基础。","frontmatter":{},"headers":[],"relativePath":"engineering/07-security/chapter-01-security-overview.md","filePath":"engineering/07-security/chapter-01-security-overview.md"}'),l={name:"engineering/07-security/chapter-01-security-overview.md"};function n(s,t,d,c,g,y){return i(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="安全概览" tabindex="-1" data-src-line="1" data-src-file="engineering/07-security/chapter-01-security-overview.md">安全概览 <a class="header-anchor" href="#安全概览" aria-label="Permalink to &quot;安全概览&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/07-security/chapter-01-security-overview.md"><p data-src-line="3" data-src-file="engineering/07-security/chapter-01-security-overview.md">OWASP Top 10 是 Web 应用重要安全风险的清单。了解它们是安全编码的基础。</p></blockquote><h2 id="_1-owasp-top-10-2025" tabindex="-1" data-src-line="5" data-src-file="engineering/07-security/chapter-01-security-overview.md">1. OWASP Top 10 (2025) <a class="header-anchor" href="#_1-owasp-top-10-2025" aria-label="Permalink to &quot;1. OWASP Top 10 (2025)&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="engineering/07-security/chapter-01-security-overview.md"><tr data-src-line="7" data-src-file="engineering/07-security/chapter-01-security-overview.md"><th style="text-align:left;">排名</th><th style="text-align:left;">风险</th><th style="text-align:left;">说明</th><th style="text-align:left;">防御</th></tr></thead><tbody data-src-line="9" data-src-file="engineering/07-security/chapter-01-security-overview.md"><tr data-src-line="9" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A01</td><td style="text-align:left;">访问控制失效</td><td style="text-align:left;">越权访问、服务端请求伪造（SSRF）</td><td style="text-align:left;">最小权限、服务端逐请求授权、对象级与数据级访问控制</td></tr><tr data-src-line="10" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A02</td><td style="text-align:left;">安全配置错误</td><td style="text-align:left;">默认密码、不必要的端口</td><td style="text-align:left;">最小化配置、定期审计</td></tr><tr data-src-line="11" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A03</td><td style="text-align:left;">软件供应链失效</td><td style="text-align:left;">依赖、构建、分发链路被入侵或篡改</td><td style="text-align:left;">SBOM、依赖扫描、供应链防护</td></tr><tr data-src-line="12" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A04</td><td style="text-align:left;">加密机制失效</td><td style="text-align:left;">明文存储、弱加密</td><td style="text-align:left;">强加密、密钥管理</td></tr><tr data-src-line="13" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A05</td><td style="text-align:left;">注入</td><td style="text-align:left;">SQL/NoSQL/OS 注入</td><td style="text-align:left;">参数化查询、输入校验</td></tr><tr data-src-line="14" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A06</td><td style="text-align:left;">不安全设计</td><td style="text-align:left;">架构层面的安全缺陷</td><td style="text-align:left;">威胁建模、安全评审</td></tr><tr data-src-line="15" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A07</td><td style="text-align:left;">认证失效</td><td style="text-align:left;">弱密码、暴力破解</td><td style="text-align:left;">MFA、限流、密码策略</td></tr><tr data-src-line="16" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A08</td><td style="text-align:left;">软件或数据完整性失效</td><td style="text-align:left;">未验证的软件与数据被信任</td><td style="text-align:left;">签名校验、完整性验证、构建流程权限控制</td></tr><tr data-src-line="17" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A09</td><td style="text-align:left;">安全日志与告警失效</td><td style="text-align:left;">安全事件难以及时发现和响应</td><td style="text-align:left;">日志、告警、SIEM</td></tr><tr data-src-line="18" data-src-file="engineering/07-security/chapter-01-security-overview.md"><td style="text-align:left;">A10</td><td style="text-align:left;">异常条件处理不当</td><td style="text-align:left;">异常路径、边界条件、失败开放</td><td style="text-align:left;">失败关闭、异常路径测试</td></tr></tbody></table><h2 id="_2-安全编码原则" tabindex="-1" data-src-line="20" data-src-file="engineering/07-security/chapter-01-security-overview.md">2. 安全编码原则 <a class="header-anchor" href="#_2-安全编码原则" aria-label="Permalink to &quot;2. 安全编码原则&quot;">​</a></h2><p data-src-line="22" data-src-file="engineering/07-security/chapter-01-security-overview.md">认证与会话管理见 <a href="./chapter-02-authentication.html">认证</a>，访问控制与数据权限见 <a href="./chapter-03-authorization.html">授权</a>；SQL 注入、XSS、CSRF 等攻击的原理与防御代码见 <a href="./chapter-04-common-attacks.html">常见攻击与防御</a>。</p><p data-src-line="24" data-src-file="engineering/07-security/chapter-01-security-overview.md">判断一个系统是否满足这些原则，需要识别资产与信任边界，分析威胁，选择控制，再验证控制有效性。</p><ol data-src-line="26" data-src-file="engineering/07-security/chapter-01-security-overview.md"><li data-src-line="26" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>最小权限</strong>：每个组件只拥有必要的权限</li><li data-src-line="27" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>纵深防御</strong>：多层安全措施，不依赖单一防线</li><li data-src-line="28" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>默认安全</strong>：默认配置应该是安全的</li><li data-src-line="29" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>输入验证</strong>：所有外部输入都不可信，校验其格式、范围与业务约束</li><li data-src-line="30" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>参数化查询</strong>：永远不要拼接 SQL</li><li data-src-line="31" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>敏感数据加密</strong>：传输用 TLS，存储用强加密</li><li data-src-line="32" data-src-file="engineering/07-security/chapter-01-security-overview.md"><strong>日志审计</strong>：记录必要的安全相关事件（身份、操作、目标资源、结果），避免记录密码、令牌等敏感凭据</li></ol>',8)])])}const u=e(l,[["render",n]]);export{f as __pageData,u as default};
